// Verilator harness for the emitted `silicon_elab_top.sv`
// (Obend.Lower.SiliconElabFabric.emitSiliconElabFabricSV = emitModuleSV siliconElabRtlModule,
// regenerated by `obend hardware emit-silicon-sv`).
//
// Expected values are read from `silicon_elab_golden.txt` (written by
// `obend-emit-sv golden-silicon-kernel` from `runVerilatorCoSimModel`).
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <map>
#include <string>

#include "Vsilicon_elab_top.h"
#include "verilated.h"
#include "verilated_vcd_c.h"

namespace {

std::map<std::string, std::string> read_golden(const char* path) {
    std::map<std::string, std::string> kv;
    std::ifstream in(path);
    std::string line;
    while (std::getline(in, line)) {
        if (line.empty() || line[0] == '#') continue;
        auto eq = line.find('=');
        if (eq == std::string::npos) continue;
        kv[line.substr(0, eq)] = line.substr(eq + 1);
    }
    return kv;
}

uint64_t golden_u64(const std::map<std::string, std::string>& g, const char* key, uint64_t fallback = 0, bool use_fallback = false) {
    auto it = g.find(key);
    if (it == g.end()) {
        if (use_fallback) return fallback;
        std::fprintf(stderr, "[FATAL] golden key missing: %s\n", key);
        std::exit(2);
    }
    return std::strtoull(it->second.c_str(), nullptr, 10);
}

// 64-bit ExprCAM word in `siliconElabRtlModule`:
//   [63:60] tag, [59] hasLooseBVar, [58] hasMVar, [31:16] h0, [15:0] h1.
uint64_t pack_cam_word64(unsigned tag, bool loose, bool mvar, unsigned h0, unsigned h1) {
    return ((uint64_t(tag) & 0xFULL) << 60) |
           ((loose ? 1ULL : 0ULL) << 59) |
           ((mvar ? 1ULL : 0ULL) << 58) |
           ((uint64_t(h0) & 0xFFFFULL) << 16) |
           (uint64_t(h1) & 0xFFFFULL);
}

struct Sim {
    Vsilicon_elab_top* top;
    VerilatedVcdC* tfp;
    uint64_t t = 0;
    uint64_t fails = 0;

    explicit Sim(const char* vcd) {
        top = new Vsilicon_elab_top;
        tfp = new VerilatedVcdC;
        top->trace(tfp, 99);
        tfp->open(vcd);
    }
    ~Sim() {
        tfp->close();
        delete tfp;
        delete top;
    }

    void tick() {
        top->clk = 0;
        top->eval();
        tfp->dump(t++);
        top->clk = 1;
        top->eval();
        tfp->dump(t++);
    }

    void idle_inputs() {
        top->cam_we = 0;
        top->cam_wr_addr = 0;
        top->cam_wr_word = 0;
        top->z1_start = 0;
        top->z1_step = 0;
        top->z1_init_handle = 0;
        top->z2_rhs_handle = 0;
        top->z3_pkt_epoch = 1;
        top->z3_pin_ok = 1;
        top->z3_rule_tag = 101;
        top->z3_arg_val = 10;
        top->dpr_cmd = 0;
        top->dpr_new_gain = 0;
        top->dpr_new_offset = 0;
        top->dpr_new_epoch = 0;
        top->z4_decl_flags = 0;
    }

    void reset() {
        idle_inputs();
        top->rst = 1;
        top->eval();
        tick();
        tick();
        top->rst = 0;
        tick();
    }

    void write_cam_slot(unsigned slot, unsigned tag, bool loose, bool mvar, unsigned h0, unsigned h1) {
        top->cam_we = 1;
        top->cam_wr_addr = slot;
        top->cam_wr_word = pack_cam_word64(tag, loose, mvar, h0, h1);
        tick();
        top->cam_we = 0;
    }

    void check(bool ok, const char* what, bool verbose) {
        if (!ok) {
            std::fprintf(stderr, "[FAIL] %s\n", what);
            fails++;
        } else if (verbose) {
            std::printf("[ok] %s\n", what);
        }
    }
};

}  // namespace

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    Verilated::randReset(2);
    Verilated::traceEverOn(true);

    bool frame_mode = false;
    const char* vcd_path = "silicon_elab_wave.vcd";
    const char* golden_path = "silicon_elab_golden.txt";
    if (argc >= 4 && std::strcmp(argv[1], "--frame") == 0) {
        frame_mode = true;
        vcd_path = argv[3];
    } else {
        if (argc > 1) vcd_path = argv[1];
        if (argc > 2) golden_path = argv[2];
    }

    auto g = read_golden(golden_path);
    const uint64_t g_epoch1 = golden_u64(g, "epoch1_lut_out", 42, frame_mode);
    const uint64_t g_epoch2 = golden_u64(g, "epoch2_lut_out", 70, frame_mode);
    const bool g_moved_pin = golden_u64(g, "moved_pin_fallback", 1, frame_mode) != 0;
    const bool g_clamped = golden_u64(g, "dpr_glitch_free_clamped", 1, frame_mode) != 0;
    const bool g_tooth = golden_u64(g, "tooth_mutant_refused", 1, frame_mode) != 0;
    const bool g_sorry = golden_u64(g, "sorry_refused", 1, frame_mode) != 0;
    const bool verbose = !frame_mode;

    Sim s(vcd_path);
    s.reset();

    // Zone 1 CAM slots:
    //   slot 0 = lit 42 (tag 8, closed)
    //   slot 1 = lam (tag 5, closed, body h1 = slot 0)
    //   slot 2 = app (tag 4, closed, fn h0 = slot 1, arg h1 = slot 0)
    //   slot 3 = app carrying an mvar (tag 4, hasMVar = true)
    s.write_cam_slot(0, 8, false, false, 42, 0);
    s.write_cam_slot(1, 5, false, false, 0,  0);
    s.write_cam_slot(2, 4, false, false, 1,  0);
    s.write_cam_slot(3, 4, false, true,  1,  0);

    // Load handle 2 and verify Zone-2 O(1) handle equality short-circuit + 1-cycle closed beta bypass.
    s.top->z1_start = 1;
    s.top->z1_init_handle = 2;
    s.top->z2_rhs_handle = 2;
    s.tick();
    s.top->z1_start = 0;
    s.top->eval();
    s.check(s.top->z2_handle_eq_out == 1, "zone2: handle equality short-circuit (2 == 2)", verbose);

    s.top->z1_step = 1;
    s.tick();
    s.top->z1_step = 0;
    s.top->eval();
    s.check(s.top->z1_bypass_out == 1 && s.top->z1_focus_out == 0 && s.top->z1_steps_out == 1,
            "zone1: (lam . 42) arg bypasses to body handle 0 in one evaluation cycle", verbose);

    // Zone 2 Bit-58 MVar scope flag on slot 3.
    s.top->z1_start = 1;
    s.top->z1_init_handle = 3;
    s.tick();
    s.top->z1_start = 0;
    s.top->eval();
    s.check(s.top->z2_mvar_bit58_out == 1, "zone2: bit-58 mvar flag detects mvar-bearing handle 3", verbose);

    // Zone 3 Epoch-1 LUT + compiled DiscrTree priority TCAM hit (gain 4, offset 2, arg 10 -> 42).
    s.top->z3_pkt_epoch = 1;
    s.top->z3_pin_ok = 1;
    s.top->z3_rule_tag = 101;
    s.top->z3_arg_val = 10;
    s.top->eval();
    s.check(s.top->z3_fast_path_out == 1 && s.top->z3_fallback_zone1_out == 0 &&
            s.top->z3_lut_val_out == g_epoch1 && s.top->z3_tcam_val_out == g_epoch1,
            "zone3: epoch-1 LUT and compiled TCAM match Lean golden epoch1_lut_out", verbose);

    // moved_pin_blocks: packet epoch 2 against pinned epoch 1 triggers 1-cycle fallback to Zone 1.
    s.top->z3_pkt_epoch = 2;
    s.top->eval();
    const bool hw_moved_pin = (s.top->z3_fast_path_out == 0) && (s.top->z3_fallback_zone1_out == 1);
    s.check(hw_moved_pin == g_moved_pin, "zone3: moved-pin fallback matches Lean golden", verbose);
    s.top->z3_pkt_epoch = 1;

    // 3-phase glitch-free ICAP DPR hot-swap:
    //   Phase 1 (cmd=1): isolate fence and latch skid output (g_epoch1 = 42),
    //   Phase 2 (cmd=2): load (epoch=2, gain=6, offset=10) while clamped at 42,
    //   Phase 3 (cmd=3): release fence and serve g_epoch2 (70) at epoch 2.
    s.top->dpr_cmd = 1;
    s.tick();
    s.top->dpr_cmd = 0;
    s.top->eval();
    const bool held_during_isolate =
        (s.top->dpr_isolated_out == 1) && (s.top->z3_lut_val_out == g_epoch1) && (s.top->z3_fast_path_out == 0);

    s.top->dpr_cmd = 2;
    s.top->dpr_new_gain = 6;
    s.top->dpr_new_offset = 10;
    s.top->dpr_new_epoch = 2;
    s.tick();
    s.top->dpr_cmd = 0;
    s.top->eval();
    const bool held_during_load =
        (s.top->dpr_isolated_out == 1) && (s.top->z3_lut_val_out == g_epoch1);

    s.top->dpr_cmd = 3;
    s.top->z3_pkt_epoch = 2;
    s.tick();
    s.top->dpr_cmd = 0;
    s.top->eval();
    const bool released =
        (s.top->dpr_isolated_out == 0) && (s.top->z3_lut_val_out == g_epoch2) && (s.top->z3_fast_path_out == 1);
    s.check((held_during_isolate && held_during_load && released) == g_clamped,
            "zone3: 3-phase DPR clamps at skid output and releases to Lean golden epoch2_lut_out", verbose);

    // Zone 4 root-of-trust gate: [bit0=sorry, bit1=mvar, bit2=sortOk, bit3=defeqOk, bit4=latch]
    // 1) Clean well-typed declaration (0b11100 = 0x1C) -> status 1, accepted 1
    s.top->z4_decl_flags = 0x1C;
    s.tick();
    s.top->z4_decl_flags = 0;
    s.top->eval();
    s.check(s.top->z4_accepted_out == 1 && s.top->z4_status_out == 1,
            "zone4: clean kernel-checked declaration accepted (status 1)", verbose);

    // 2) #tooth ill-typed mutant (sortOk=1, defeqOk=0, latch=1 -> 0b10100 = 0x14) -> status 2, accepted 0
    s.top->z4_decl_flags = 0x14;
    s.tick();
    s.top->z4_decl_flags = 0;
    s.top->eval();
    const bool hw_tooth = (s.top->z4_accepted_out == 0) && (s.top->z4_status_out == 2);
    s.check(hw_tooth == g_tooth, "zone4: ill-typed mutant refused matches Lean golden", verbose);

    // 3) sorryAx contamination (sorry=1, sortOk=1, defeqOk=1, latch=1 -> 0b11101 = 0x1D) -> status 0, accepted 0
    s.top->z4_decl_flags = 0x1D;
    s.tick();
    s.top->z4_decl_flags = 0;
    s.top->eval();
    const bool hw_sorry = (s.top->z4_accepted_out == 0) && (s.top->z4_status_out == 0);
    s.check(hw_sorry == g_sorry, "zone4: sorryAx refused matches Lean golden", verbose);

    // 4) Universe sort mismatch (sortOk=0, defeqOk=1, latch=1 -> 0b11000 = 0x18) -> status 3, accepted 0
    s.top->z4_decl_flags = 0x18;
    s.tick();
    s.top->z4_decl_flags = 0;
    s.top->eval();
    s.check(s.top->z4_accepted_out == 0 && s.top->z4_status_out == 3,
            "zone4: universe sort mismatch reports status 3", verbose);

    std::printf("{\"status\":\"%s\",\"fails\":%llu,\"vcd\":\"%s\",\"golden\":\"%s\"}\n",
                s.fails == 0 ? "PASS" : "FAIL",
                static_cast<unsigned long long>(s.fails),
                vcd_path,
                golden_path);
    return s.fails == 0 ? 0 : 1;
}
